  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('total' in totals);
});

test('invoiceTotals calculates discount correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  // DES-HOUR: 2 * 8500 = 17000 cents
  // Discount: 17000 * 10 / 100 = 1700 cents
  // Amount after discount: 15300
  // VAT: 15300 * 21 / 100 = 3213 cents
  // Total: 17000 - 1700 + 3213 = 18513
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.vat, 3213);
  assert.equal(totals.total, 18513);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
    ],
  }).value;

  // DES-HOUR: 2 * 8500 = 17000, discount = 1700, amount = 15300, VAT = 15300 * 21% = 3213
  // DEV-HOUR: 1 * 9500 = 9500, discount = 1900, amount = 7600, VAT = 7600 * 21% = 1596
  // Total VAT: 4809
  // Total: 26500 - 3600 + 4809 = 27709
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 26500);
  assert.equal(totals.discount, 3600);
  assert.equal(totals.vat, 4809);
  assert.equal(totals.total, 27709);
});

