  const result = applyVoucher(invoice, { code: 'SAVE100', amount: 50000 });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.voucher, 50000);
  assert.equal(totals.total, 10500); // 50000 - 0 + 10500 - 50000
});

test('applyVoucher with voucher exceeding total still applies', () => {
