    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  invoice.status = 'issued';

  const result = issueInvoice(invoice, []);
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

