test('applyVoucher with large voucher amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DESK', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SAVE100', amount: 50000 });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.voucher, 50000);
  assert.equal(totals.total, 10500); // 50000 - 0 + 10500 - 50000
});

test('applyVoucher with voucher exceeding total still applies', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DESK', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SAVEBIG', amount: 100000 });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.total, 0); // clamped at 0: 50000 - 0 + 10500 - 100000 = -39500 → 0
});
